// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: the multi-select of tool forms (render._multi_select), for any tool parameter typed
//          list[<a fixed set of values>] (tool_forms.list_choices): each pick is a chip (icon +
//          name + ×) in the box, and a text box after the chips filters a list to add more.
// Markup it drives (all rendered by Reflex, found by data- attributes):
//   [data-multi]          the wrapper (the box); gets .is-open while the list shows
//   [data-multi-chips]    the picks as chips; this script owns its contents
//   [data-multi-text]     the text box: type to filter the list
//   [data-multi-value]    the hidden input the form submits: picked values joined by "," ("" = any)
//   [data-multi-list]     the options: .multi-option buttons with data-value, data-label, data-icon
// Click / Enter on an option ticks or unticks it and keeps the list open; × on a chip or Backspace
// in the empty text box removes a pick; Escape / Tab / a click outside closes; Enter with the list
// closed runs the form. One set of listeners on document, so selects Reflex mounts later just work.
// ---------------------------------------------------------------------------
(() => {
  const parts = (el) => {
    const multi = el.closest?.("[data-multi]");
    if (!multi) return null;
    return {
      multi,
      chips: multi.querySelector("[data-multi-chips]"),
      text: multi.querySelector("[data-multi-text]"),
      value: multi.querySelector("[data-multi-value]"),
      list: multi.querySelector("[data-multi-list]"),
    };
  };
  const options = (p) => [...p.list.querySelectorAll(".multi-option")];
  const visible = (p) => options(p).filter((o) => !o.hidden);
  const active = (p) => p.list.querySelector(".multi-option.is-active");
  const picked = (p) => p.value.value.split(",").filter(Boolean);
  const isOpen = (p) => p.multi.classList.contains("is-open");

  // the chips (in pick order) and the ✓ marks, from the hidden value
  const render = (p) => {
    const values = picked(p);
    const byValue = new Map(options(p).map((o) => [o.dataset.value, o]));
    options(p).forEach((o) => o.classList.toggle("is-picked", values.includes(o.dataset.value)));
    p.chips.replaceChildren(
      ...values.map((value) => {
        const o = byValue.get(value);
        const chip = document.createElement("span");
        chip.className = "multi-chip";
        if (o?.dataset.icon) {
          const img = document.createElement("img");
          img.src = o.dataset.icon;
          img.alt = "";
          img.className = "char-icon";
          chip.append(img);
        }
        const label = document.createElement("span");
        label.textContent = o ? o.dataset.label : value;
        const remove = document.createElement("button");
        remove.type = "button";
        remove.tabIndex = -1;
        remove.className = "multi-remove";
        remove.dataset.multiRemove = value;
        remove.title = `Remove ${label.textContent}`;
        remove.textContent = "×";
        chip.append(label, remove);
        return chip;
      }),
    );
    p.text.placeholder = values.length ? "" : "any";
    if (isOpen(p)) place(p); // the box may have grown a line
  };

  const setPicked = (p, values) => {
    p.value.value = values.join(",");
    render(p);
  };
  const toggle = (p, value) => {
    const values = picked(p);
    setPicked(p, values.includes(value) ? values.filter((v) => v !== value) : [...values, value]);
  };

  // scroll only the list (never scrollIntoView: that can scroll the tab around it, which closes the list)
  const setActive = (p, option) => {
    options(p).forEach((o) => o.classList.toggle("is-active", o === option));
    if (!option) return;
    const top = option.offsetTop;
    const bottom = top + option.offsetHeight;
    if (top < p.list.scrollTop) p.list.scrollTop = top;
    else if (bottom > p.list.scrollTop + p.list.clientHeight) p.list.scrollTop = bottom - p.list.clientHeight;
  };
  const filter = (p) => {
    const wanted = p.text.value.trim().toLowerCase();
    options(p).forEach((o) => {
      const hay = `${o.dataset.label} ${o.dataset.value}`.toLowerCase();
      o.hidden = wanted !== "" && !hay.includes(wanted);
    });
    setActive(p, visible(p)[0] || null);
  };

  // position: fixed under (or above) the box, so a scrolling parent (a result tab) can't clip it
  const place = (p) => {
    const box = p.multi.getBoundingClientRect();
    const below = window.innerHeight - box.bottom;
    p.list.style.left = `${Math.min(box.left, window.innerWidth - 250)}px`;
    p.list.style.minWidth = `${Math.max(box.width, 200)}px`;
    if (below < 240 && box.top > below) {
      p.list.style.top = "";
      p.list.style.bottom = `${window.innerHeight - box.top + 2}px`;
      p.list.style.maxHeight = `${Math.min(320, box.top - 8)}px`;
    } else {
      p.list.style.bottom = "";
      p.list.style.top = `${box.bottom + 2}px`;
      p.list.style.maxHeight = `${Math.min(320, below - 8)}px`;
    }
  };

  const open = (p) => {
    document.querySelectorAll("[data-multi].is-open").forEach((m) => m !== p.multi && m.classList.remove("is-open"));
    p.multi.classList.add("is-open");
    filter(p);
    place(p);
  };
  const close = (p) => {
    p.multi.classList.remove("is-open");
    p.text.value = "";
  };

  // a select Reflex just mounted: show what its hidden value holds
  const init = (root) => {
    root.querySelectorAll?.("[data-multi]:not([data-multi-ready])").forEach((multi) => {
      multi.dataset.multiReady = "1";
      render(parts(multi));
    });
  };
  new MutationObserver((changes) => changes.forEach((c) => c.addedNodes.forEach((n) => n.nodeType === 1 && init(n.parentNode || n))))
    .observe(document.documentElement, { childList: true, subtree: true });
  document.addEventListener("DOMContentLoaded", () => init(document));

  // mousedown, not click: it comes before the text box loses focus, and preventDefault keeps the
  // focus there (the field sits in a <label>, whose click would also refocus the first control)
  document.addEventListener("mousedown", (event) => {
    const p = parts(event.target);
    if (!p) {
      document.querySelectorAll("[data-multi].is-open").forEach((m) => close(parts(m)));
      return;
    }
    if (event.target === p.text) return; // the browser places the caret; focusin opens
    event.preventDefault();
    const remove = event.target.closest("[data-multi-remove]");
    const option = event.target.closest(".multi-option");
    if (remove) toggle(p, remove.dataset.multiRemove);
    else if (option) {
      toggle(p, option.dataset.value);
      p.text.value = "";
      filter(p);
      setActive(p, option);
    }
    p.text.focus();
    if (!isOpen(p) && !remove) open(p);
  });
  // the label's click would otherwise move focus / "click" its first button
  document.addEventListener("click", (event) => {
    if (parts(event.target) && event.target.closest("[data-multi-list], [data-multi-remove]")) event.preventDefault();
  });

  document.addEventListener("focusin", (event) => {
    if (event.target.matches?.("[data-multi-text]")) open(parts(event.target));
  });
  document.addEventListener("focusout", (event) => {
    if (event.target.matches?.("[data-multi-text]")) close(parts(event.target));
  });
  document.addEventListener("input", (event) => {
    if (!event.target.matches?.("[data-multi-text]")) return;
    const p = parts(event.target);
    if (!isOpen(p)) open(p);
    filter(p);
  });

  document.addEventListener(
    "keydown",
    (event) => {
      if (!event.target.matches?.("[data-multi-text]")) return;
      const p = parts(event.target);
      if (event.key === "Backspace" && p.text.value === "" && picked(p).length) {
        event.preventDefault();
        setPicked(p, picked(p).slice(0, -1));
      } else if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        if (!isOpen(p)) return open(p);
        const shown = visible(p);
        const at = shown.indexOf(active(p));
        const next = event.key === "ArrowDown" ? Math.min(at + 1, shown.length - 1) : Math.max(at - 1, 0);
        setActive(p, shown[next] || null);
      } else if (event.key === "Enter" && isOpen(p)) {
        // the list is open: Enter ticks the active option; it never runs the form
        event.preventDefault();
        event.stopPropagation();
        const option = active(p);
        if (option) {
          toggle(p, option.dataset.value);
          p.text.value = "";
          filter(p);
          setActive(p, option);
        }
      } else if (event.key === "Escape" && isOpen(p)) {
        // capture phase + stop: Esc closes this list, not the floating view around it (panes.js)
        event.preventDefault();
        event.stopPropagation();
        close(p);
      }
    },
    true,
  );

  // an open list is in the wrong place once the page scrolls or resizes: close it
  const closeAll = (event) => {
    if (event?.target?.closest?.("[data-multi-list]")) return; // scrolling the list itself
    document.querySelectorAll("[data-multi].is-open").forEach((m) => m.classList.remove("is-open"));
  };
  window.addEventListener("scroll", closeAll, true);
  window.addEventListener("resize", closeAll);
})();
